// ==UserScript==
// @name			Humble Bundle - Named file downloader
// @description		Trigger scan and download though Simple mass downloader or GM_download
// @namespace		HumbleBundle
// @version			1.0
// @author			QuidamAzerty & Generated by Lumo AI
// @match			https://www.humblebundle.com/home/library*
// @match			https://www.humblebundle.com/home/library/*
// @match			https://www.humblebundle.com/downloads*
// @grant			GM_download
// @connect			cdn.humble.com
// @connect			dl.humble.com
// @run-at			document-idle
// ==/UserScript==

(function () {
	'use strict';

	const LOG = (...a) => console.log('%c[HB-DL]', 'color:#6d4aff;font-weight:bold', ...a);

	/* ================= 1. NETWORK INTERCEPTION (fetch + XHR) ================= */
	const capturedSources = [];

	function maybeCapture(text, src) {
		if (typeof text !== 'string' || text.indexOf('signedUrls') === -1) return false;
		if (capturedSources.some(c => c.text === text)) return true;
		capturedSources.push({src: src || 'réseau', text});
		LOG('réponse réseau capturée depuis', src, '(' + (text.length / 1000).toFixed(0) + ' ko, contient signedUrls)');
		return true;
	}

	if (!window.__hbDlHooked) {
		window.__hbDlHooked = true;
		const origFetch = window.fetch;
		window.fetch = async function (...args) {
			const res = await origFetch.apply(this, args);
			try {
				res.clone().text().then(t => {
					maybeCapture(t, 'fetch ' + String(args[0]).slice(0, 120));
				}).catch(() => {
				});
			} catch (e) {
			}
			return res;
		};
		const origOpen = XMLHttpRequest.prototype.open;
		XMLHttpRequest.prototype.open = function (method, url) {
			this._hbDlUrl = url;
			return origOpen.apply(this, arguments);
		};
		const origSend = XMLHttpRequest.prototype.send;
		XMLHttpRequest.prototype.send = function () {
			this.addEventListener('load', function () {
				try {
					maybeCapture(this.responseText, 'xhr ' + String(this._hbDlUrl).slice(0, 120));
				} catch (e) {
				}
			});
			return origSend.apply(this, arguments);
		};
		LOG('hooks fetch/XHR installés');
	}

	/* ================= 2. PAYLOAD NEXT.JS ================= */
	function getFlightPayload() {
		const chunks = [];
		for (const s of document.querySelectorAll('script')) {
			const txt = s.textContent || '';
			if (txt.indexOf('__next_f') === -1) continue;
			const re = /self\.__next_f\.push\(\[\s*(\d)\s*,\s*("(?:[^"\\]|\\.)*")\s*\]\)/g;
			let m;
			while ((m = re.exec(txt))) {
				try {
					if (m[1] === '1') chunks.push(JSON.parse(m[2]));
				} catch (e) {
				}
			}
		}
		return chunks.join('');
	}

	/* ================= 3. UTILITIES ================= */
	function sliceBalanced(text, start) {
		const open = text[start];
		const close = open === '{' ? '}' : ']';
		let depth = 0, inStr = false, esc = false;
		for (let i = start; i < text.length; i++) {
			const ch = text[i];
			if (inStr) {
				if (esc) esc = false;
				else if (ch === '\\') esc = true;
				else if (ch === '"') inStr = false;
			} else {
				if (ch === '"') inStr = true;
				else if (ch === open) depth++;
				else if (ch === close) {
					depth--;
					if (depth === 0) return text.slice(start, i + 1);
				}
			}
		}
		return null;
	}

	const tryParse = (s) => {
		try {
			return JSON.parse(s);
		} catch (e) {
			return undefined;
		}
	};

	function encodePath(p) {
		return p.split('/').map(seg =>
			encodeURIComponent(seg).replace(/[!'()*]/g, c => '%' + c.charCodeAt(0).toString(16).toUpperCase())
		).join('/');
	}

	function cleanTitle(t) {
		return t.replace(/[\\/:*?"<>|]+/g, '-').replace(/\s+/g, ' ').trim();
	}

	function fmtSize(b) {
		if (!b) return '';
		const u = ['o', 'Ko', 'Mo', 'Go'];
		let i = 0;
		while (b >= 1024 && i < u.length - 1) {
			b /= 1024;
			i++;
		}
		return (b >= 100 || i === 0 ? b.toFixed(0) : b.toFixed(1)) + ' ' + u[i];
	}

	function extOf(item) {
		const m = /\.([a-z0-9]+)(\?|$)/i.exec(item.fileName || '');
		return m ? m[1].toLowerCase() : (String(item.name).toLowerCase() || 'bin');
	}

	function filenameOf(item) {
		const ext = extOf(item);
		const base = item.title || item.fileName.replace(/\.[a-z0-9]+$/i, '') || 'fichier';
		return base + (['cbz', 'pdf'].includes(ext) ? '' : '.' + item.name.toLowerCase()) + '.' + ext;
	}

	/* ================= 4. EXTRACTION ================= */
	function extractFromText(text, stats) {
		const items = [];
		let expiresAt = null;
		const miss = {noDownloads: 0, badParse: 0, noUrl: 0, noTitle: 0};

		const titles = [];
		const tRe = /"title":"((?:[^"\\]|\\.)*)"/g;
		let tM;
		while ((tM = tRe.exec(text))) titles.push({pos: tM.index, raw: tM[1]});
		stats.titles += titles.length;

		// Positions of all "downloads":[ ... ] arrays
		const dlPositions = [];
		const dlRe = /"downloads"\s*:\s*\[/g;
		let dM;
		while ((dM = dlRe.exec(text))) dlPositions.push({pos: dM.index, arrStart: dM.index + dM[0].length - 1});

		// Outer "signedUrls" blocks (object with subproductMachineName/expiresAt)
		const suRe = /"signedUrls"\s*:\s*\{/g;
		let m, blocks = 0;
		while ((m = suRe.exec(text))) {
			blocks++;
			const suObj = tryParse(sliceBalanced(text, m.index + m[0].length - 1));
			if (!suObj || !suObj.signedUrls) continue; // inner block ("signedUrls":{...}) or unparseable
			if (suObj.expiresAt) expiresAt = suObj.expiresAt;

			const machine = suObj.subproductMachineName || Object.keys(suObj.signedUrls)[0];
			if (!machine) continue;
			const map = suObj.signedUrls[machine] || {};
			if (!Object.keys(map).length) continue; // e.g. "No Content" item

			// closest "downloads" array BEFORE this block
			let dl = null;
			for (let i = dlPositions.length - 1; i >= 0; i--) {
				if (dlPositions[i].pos < m.index) {
					dl = dlPositions[i];
					break;
				}
			}
			if (!dl) {
				miss.noDownloads++;
				continue;
			}
			const downloads = tryParse(sliceBalanced(text, dl.arrStart));
			if (!Array.isArray(downloads)) {
				miss.badParse++;
				continue;
			}

			let title = 'Sans titre';
			for (const t of titles) {
				if (t.pos > dl.pos) break;
				title = t.raw;
			}
			if (title === 'Sans titre') miss.noTitle++;
			try {
				title = JSON.parse('"' + title + '"');
			} catch (e) {
			}

			for (const d of downloads) {
				if (!d || !Array.isArray(d.downloadStruct)) continue;
				for (const ds of d.downloadStruct) {
					const web = ds && ds.url && (ds.url.web || ds.url.bittorrent);
					if (!web) continue;
					const signed = (map[d.key] || {})[encodePath(web)];
					if (!signed) {
						miss.noUrl++;
						LOG('URL absente pour', title, '/', ds.name, '| key:', d.key,
							'| cherché:', encodePath(web), '| clés dispo:', Object.keys(map[d.key] || {}).slice(0, 4).join(', '));
						continue;
					}
					items.push({
						title: cleanTitle(title),
						name: (ds.name || '').toUpperCase(),
						size: ds.fileSize || 0,
						fileName: (web.split('/').pop() || ''),
						url: signed
					});
				}
			}
		}
		stats.blocks += blocks;
		stats.miss = stats.miss || {noDownloads: 0, badParse: 0, noUrl: 0, noTitle: 0};
		for (const k of Object.keys(miss)) stats.miss[k] += miss[k];
		items.expiresAt = expiresAt;
		return items;
	}

	/* ================= 5. DIAGNOSTIC ================= */
	function countIn(text, needle) {
		let n = 0, i = -1;
		while ((i = text.indexOf(needle, i + 1)) !== -1) n++;
		return n;
	}

	function diagReport(sources) {
		const needles = ['"signedUrls"', '"downloadStruct"', '"cdn.humble.com"', '"dl.humble.com"', 'hmac=', '"expiresAt"', '"subproductMachineName"'];
		const lines = ['Sources scannées : ' + sources.length];
		for (const s of sources) {
			lines.push('\n=== ' + s.src + ' (' + (s.text.length / 1000).toFixed(0) + ' ko) ===');
			for (const nd of needles) {
				const c = countIn(s.text, nd);
				if (c) lines.push('  ' + nd + ' : ' + c);
			}
			if (!needles.some(nd => countIn(s.text, nd))) lines.push('  (aucun marqueur de téléchargement)');
		}
		return lines.join('\n');
	}

	/* ================= 6. PANEL (persistent, incremental) ================= */
	let seenUrls = new Set();
	let allRows = [];
	let listEl = null;
	let headCount = null;
	let expInfo = null;
	let expiresAt = null;

	function showDiag(text) {
		closePanel();
		const panel = document.createElement('div');
		panel.id = 'hb-dl-panel';
		panel.style.cssText =
			'position:fixed;top:10px;right:10px;z-index:2147483647;width:520px;max-height:82vh;' +
			'display:flex;flex-direction:column;background:#16131f;color:#eee;' +
			'font:12px/1.4 monospace;border:1px solid #b33;border-radius:10px;box-shadow:0 6px 24px rgba(0,0,0,.55)';
		const head = document.createElement('div');
		head.style.cssText = 'padding:10px 12px;background:#b33;color:#fff;font-family:system-ui;border-radius:9px 9px 0 0';
		head.innerHTML = '<b>Aucun nouveau lien trouvé – rapport diagnostic</b><br>Copie ce texte et renvoie-le-moi.';
		panel.appendChild(head);
		const ta = document.createElement('textarea');
		ta.value = text;
		ta.style.cssText = 'flex:1;margin:8px 12px;background:#0d0b14;color:#ccc;border:1px solid #333;border-radius:6px;padding:8px;white-space:pre;overflow:auto';
		panel.appendChild(ta);
		const bar = document.createElement('div');
		bar.style.cssText = 'padding:0 12px 10px;display:flex;gap:8px';
		const btnCopy = document.createElement('button');
		btnCopy.textContent = 'Copier le rapport';
		btnCopy.style.cssText = 'cursor:pointer;border:0;border-radius:6px;padding:6px 12px;background:#6d4aff;color:#fff;font:12px system-ui';
		btnCopy.onclick = () => {
			ta.select();
			try {
				document.execCommand('copy');
			} catch (e) {
			}
		};
		const btnClose = document.createElement('button');
		btnClose.textContent = 'Fermer';
		btnClose.style.cssText = 'cursor:pointer;border:0;border-radius:6px;padding:6px 12px;background:#3a3552;color:#eee;font:12px system-ui';
		btnClose.onclick = () => panel.remove();
		bar.append(btnCopy, btnClose);
		panel.appendChild(bar);
		document.body.appendChild(panel);
	}

	function closePanel() {
		document.getElementById('hb-dl-panel')?.remove();
		listEl = null;
		headCount = null;
		expInfo = null;
		allRows = [];
		seenUrls = new Set();
		expiresAt = null;
	}

	function ensurePanel() {
		if (listEl) return;
		closePanel();
		const panel = document.createElement('div');
		panel.id = 'hb-dl-panel';
		panel.style.cssText =
			'position:fixed;top:10px;right:10px;z-index:2147483647;width:400px;max-height:82vh;' +
			'display:flex;flex-direction:column;background:#16131f;color:#eee;' +
			'font:13px/1.45 system-ui,sans-serif;border:1px solid #6d4aff;border-radius:10px;' +
			'box-shadow:0 6px 24px rgba(0,0,0,.55)';

		const head = document.createElement('div');
		head.style.cssText = 'padding:10px 12px;background:#6d4aff;border-radius:9px 9px 0 0';
		headCount = document.createElement('b');
		headCount.textContent = 'Humble Bundle – 0 fichier';
		head.appendChild(headCount);
		expInfo = document.createElement('div');
		expInfo.style.cssText = 'font-size:11px;opacity:.9';
		head.appendChild(expInfo);
		panel.appendChild(head);

		const bar = document.createElement('div');
		bar.style.cssText = 'padding:8px 12px;display:flex;flex-wrap:wrap;gap:8px;align-items:center;border-bottom:1px solid #333';
		const mkBtn = (label, bg) => {
			const b = document.createElement('button');
			b.textContent = label;
			b.style.cssText = 'cursor:pointer;border:0;border-radius:6px;padding:4px 10px;font-size:12px;background:' + (bg || '#3a3552') + ';color:#eee';
			return b;
		};
		const chkCbz = document.createElement('input');
		chkCbz.type = 'checkbox';
		chkCbz.checked = true;
		const chkPdf = document.createElement('input');
		chkPdf.type = 'checkbox';
		chkPdf.checked = true;
		const lblCbz = document.createElement('label'), lblPdf = document.createElement('label');
		lblCbz.append(chkCbz, ' CBZ ');
		lblPdf.append(chkPdf, ' PDF ');
		lblCbz.style.cssText = lblPdf.style.cssText = 'font-size:12px';
		const btnDl = mkBtn('\u25bc Tout (GM_download)', '#6d4aff');
		const btnCopy = mkBtn('\u29c9 Copier URL \\t Nom');
		const btnClear = mkBtn('\u2715 Vider');
		bar.append(lblCbz, lblPdf, btnDl, btnCopy, btnClear);
		panel.appendChild(bar);

		listEl = document.createElement('div');
		listEl.style.cssText = 'overflow:auto;padding:6px 10px 10px';
		panel.appendChild(listEl);

		const applyFilter = () => {
			for (const r of allRows) {
				const e = r.ext;
				r.row.style.display = (e === 'CBZ' && chkCbz.checked) || (e === 'PDF' && chkPdf.checked) || (!['CBZ', 'PDF'].includes(e)) ? '' : 'none';
			}
		};
		chkCbz.onchange = chkPdf.onchange = applyFilter;

		btnCopy.onclick = () => {
			const lines = allRows.filter(r => r.row.style.display !== 'none')
				.map(r => r.url + '\t' + r.filename).join('\n');
			if (navigator.clipboard && navigator.clipboard.writeText) {
				navigator.clipboard.writeText(lines).catch(() => fallbackCopy(lines));
			} else fallbackCopy(lines);
			LOG('Liste copiée (' + lines.split('\n').length + ' lignes)');
		};

		function fallbackCopy(txt) {
			const ta = document.createElement('textarea');
			ta.value = txt;
			ta.style.position = 'fixed';
			ta.style.opacity = '0';
			document.body.appendChild(ta);
			ta.select();
			try {
				document.execCommand('copy');
			} catch (e) {
			}
			ta.remove();
		}

		btnClear.onclick = () => {
			closePanel();
			LOG('Panneau vidé');
		};

		let seqRunning = false;
		btnDl.onclick = async () => {
			if (seqRunning) {
				seqRunning = false;
				btnDl.textContent = '\u25bc Stop';
				return;
			}
			seqRunning = true;
			btnDl.textContent = '\u25bc Stop';
			const targets = allRows.filter(r => r.row.style.display !== 'none');
			LOG('Téléchargement séquentiel (GM_download) de', targets.length, 'fichiers…');
			let ok = 0, fail = 0;
			for (const r of targets) {
				if (!seqRunning) break;
				r.anchor.style.color = '#ffd479';
				try {
					await new Promise(res => {
						GM_download({
							url: r.url, name: r.filename,
							onload: () => {
								ok++;
								r.anchor.style.color = '#7dd87d';
								res();
							},
							onerror: (e) => {
								fail++;
								LOG('échec', r.filename, e && e.error);
								r.anchor.style.color = '#ff8f8f';
								res();
							},
							onprogress: () => {
							}
						});
					});
				} catch (e) {
					fail++;
					LOG('erreur GM_download', e);
				}
				await new Promise(r2 => setTimeout(r2, 500));
			}
			LOG('Terminé :', ok, 'ok,', fail, 'échecs');
			seqRunning = false;
			btnDl.textContent = '\u25bc Tout (GM_download)';
		};

		document.body.appendChild(panel);
	}

	function addItems(items) {
		ensurePanel();
		let added = 0;
		for (const it of items) {
			if (seenUrls.has(it.url)) continue;
			seenUrls.add(it.url);
			const filename = filenameOf(it);
			const ext = extOf(it).toUpperCase();

			const row = document.createElement('div');
			row.style.cssText = 'display:flex;align-items:flex-start;gap:6px;padding:3px 2px';

			const dlIcon = document.createElement('span');
			dlIcon.textContent = '\u25bc';
			dlIcon.title = 'Télécharger ce fichier (GM_download, nom conservé)';
			dlIcon.style.cssText = 'cursor:pointer;color:#6d4aff;font-size:12px;flex-shrink:0;padding-top:2px';
			dlIcon.onclick = () => {
				GM_download({
					url: it.url, name: filename,
					onload: () => {
						anchor.style.color = '#7dd87d';
						LOG('ok :', filename);
					},
					onerror: (e) => {
						LOG('échec', filename, e && e.error);
						anchor.style.color = '#ff8f8f';
					}
				});
			};

			const anchor = document.createElement('a');
			anchor.href = it.url;
			anchor.download = filename;
			anchor.textContent = filename + (it.size ? ' (' + fmtSize(it.size) + ')' : '');
			anchor.style.cssText = 'color:#9d8cff;text-decoration:none;word-break:break-all;flex:1';
			anchor.title = it.title;

			row.append(dlIcon, anchor);
			listEl.appendChild(row);
			allRows.push({row, anchor, ext, filename, url: it.url});
			added++;
		}

		headCount.textContent = 'Humble Bundle – ' + allRows.length + ' fichiers';
		if (expiresAt) {
			const exp = new Date(expiresAt);
			const left = exp - Date.now();
			expInfo.textContent = left > 0
				? 'Liens valables jusqu\u2019\u00e0 ' + exp.toLocaleTimeString() + ' \u2013 recharge la page ensuite.'
				: '\u26a0\ufe0f Liens EXPIR\u00c9S \u2013 recharge la page (F5) puis re-scanne.';
		}
		LOG(added > 0 ? '+' + added + ' nouveaux liens (total : ' + allRows.length + ')' : 'aucun nouveau lien (tous déjà listés)');
		return added;
	}

	/* ================= 7. SCAN (on demand only) ================= */
	function collectSources() {
		const sources = [];
		const flight = getFlightPayload();
		if (flight) sources.push({src: 'page __next_f (' + location.pathname + ')', text: flight});
		for (const s of document.querySelectorAll('script[type="application/json"]')) {
			const t = s.textContent || '';
			if (t.indexOf('signedUrls') !== -1) sources.push({src: 'script json embarqué', text: t});
		}
		for (const c of capturedSources) sources.push({src: c.src, text: c.text});
		return sources;
	}

	function scan(showDiagOnEmpty) {
		const sources = collectSources();
		const stats = {titles: 0, blocks: 0, miss: {noDownloads: 0, badParse: 0, noUrl: 0, noTitle: 0}};
		let items = [];
		for (const s of sources) {
			try {
				const it = extractFromText(s.text, stats);
				if (it.length) items = items.concat(it);
				if (it.expiresAt) expiresAt = it.expiresAt;
			} catch (e) {
				LOG('erreur extraction', s.src, e);
			}
		}
		const uniq = new Map();
		for (const it of items) if (!uniq.has(it.url)) uniq.set(it.url, it);
		items = Array.from(uniq.values());

		LOG('scan | sources:', sources.length, '| titres vus:', stats.titles,
			'| blocs signedUrls:', stats.blocks, '| liens:', items.length,
			'| manqués:', JSON.stringify(stats.miss));

		if (items.length) {
			addItems(items);
			return true;
		}
		if (showDiagOnEmpty) showDiag(diagReport(sources));
		return false;
	}

	/* ================= 8. MANUAL BUTTON (only trigger) ================= */
	function addRelaunchButton() {
		document.getElementById('hb-dl-relaunch')?.remove();
		const btn = document.createElement('button');
		btn.id = 'hb-dl-relaunch';
		btn.textContent = 'HB \ud83d\udd04 Scanner';
		btn.title = 'Rechercher les liens de t\u00e9l\u00e9chargement Humble Bundle (clic = scan, Maj+clic = diagnostic)';
		btn.style.cssText =
			'position:fixed;bottom:14px;right:14px;z-index:2147483647;cursor:pointer;' +
			'background:#6d4aff;color:#fff;border:0;border-radius:20px;padding:8px 16px;' +
			'font:13px system-ui,sans-serif;font-weight:bold;box-shadow:0 4px 14px rgba(0,0,0,.5)';
		btn.onclick = (ev) => {
			LOG('scan manuel d\u00e9clench\u00e9');
			scan(ev.shiftKey);
		};
		document.body.appendChild(btn);
	}

	addRelaunchButton();
	LOG('pr\u00eat \u2013 clique le bouton \u00ab HB \ud83d\udd04 Scanner \u00bb pour lancer l\u2019analyse');
})();
